#!/usr/bin/env node

// ────────────────────────────────────────────────────────────────
// DO NOT EDIT THIS FILE.
//
// COPY of source-of-truth at
//   ~/.claude/standards/scripts/verify/verify-e2e-db-safety.mjs
//
// Local edits will be overwritten the next time
//   bash ~/.claude/standards/scripts/install-slice-gates.sh
// runs. Edit the ORIGINAL and re-install.
// ────────────────────────────────────────────────────────────────
/**
 * verify-e2e-db-safety.mjs
 *
 * @version 1
 *
 * E2E_TESTING.yaml db_safety, mechanical. E2E tests + e2e seeds target ONLY
 * local / e2e databases:
 *   1. literal connection strings inside e2e scope must point at a local host
 *   2. DB-URL env vars consumed in e2e scope must be E2E_/TEST_/LOCAL_-scoped
 *      (never DATABASE_URL / PROD*)
 *
 * Scope: any file whose path contains an `/e2e/` segment, or lives under
 * db/seeds/e2e/. Green no-op when no e2e surface exists.
 *
 * Usage: node verify-e2e-db-safety.mjs [<root>]   (default: cwd)
 * Exit: 0 green, 1 red.
 */
import fs from "node:fs";
import path from "node:path";
import process from "node:process";

const GREEN = "\x1b[32m";
const RED = "\x1b[31m";
const RESET = "\x1b[0m";
const NAME = "verify-e2e-db-safety";

const SKIP_DIRS = new Set(["node_modules", ".git", ".next", ".turbo", "dist", "build", "coverage", "out", ".archive"]);
const CODE_EXT = /\.(ts|tsx|mts|cts|js|mjs|cjs|yaml|yml|sql|env|sh)$/;
const LOCAL_HOST = /^(localhost|127(\.\d+){3}|0\.0\.0\.0|::1|\[::1\])$|(\.(local|test|localhost))$/;
const CONN_RE = /(?:postgres(?:ql)?|mysql|mongodb(?:\+srv)?):\/\/([^\s'"`]+)/g;
const ENV_RE = /(?:process\.env\.|\$\{?)([A-Z0-9_]*(?:DATABASE|DB)_?URL[A-Z0-9_]*)/g;
const SAFE_ENV = /^(E2E|TEST|LOCAL)_/;

function* walk(dir) {
  for (const ent of fs.readdirSync(dir, { withFileTypes: true })) {
    if (ent.isDirectory()) {
      if (!SKIP_DIRS.has(ent.name)) yield* walk(path.join(dir, ent.name));
    } else yield path.join(dir, ent.name);
  }
}

function hostOf(rest) {
  // rest = everything after scheme:// — strip credentials, take host
  const noCred = rest.includes("@") ? rest.slice(rest.lastIndexOf("@") + 1) : rest;
  return noCred.split(/[:/?]/)[0];
}

const root = path.resolve(process.cwd(), process.argv[2] || ".");
const EXTRA_ROOTS = [];
// Also scan the repo-root e2e/ tree when running from a code subdir —
// the e2e contracts live at the git root (E2E_TESTING placement.mono).
import { execSync } from "node:child_process";
try {
  const top = execSync("git rev-parse --show-toplevel", { encoding: "utf8" }).trim();
  const rootE2e = path.join(top, "e2e");
  if (fs.existsSync(rootE2e) && !path.resolve(root).startsWith(top + path.sep + "e2e") && path.resolve(root) !== rootE2e) {
    EXTRA_ROOTS.push(rootE2e);
  }
} catch { /* not a git repo */ }

const violations = [];
let scanned = 0;

for (const f of [...(fs.existsSync(root) ? [...walk(root)] : []), ...EXTRA_ROOTS.flatMap((r) => [...walk(r)])]) {
  const rel = path.relative(root, f);
  const inScope = /(^|\/)e2e\//.test(rel) || /(^|\/)db\/seeds\/e2e\//.test(rel);
  if (!inScope || !CODE_EXT.test(rel)) continue;
  scanned++;
  const text = fs.readFileSync(f, "utf8");

  for (const m of text.matchAll(CONN_RE)) {
    if (m[1].startsWith("$")) continue; // templated — judged by the env-var rule
    const host = hostOf(m[1]);
    if (host && !LOCAL_HOST.test(host)) {
      violations.push({ rel, rule: `non-local DB connection string (host "${host}") — e2e scope may only target local/e2e databases` });
    }
  }
  for (const m of text.matchAll(ENV_RE)) {
    if (!SAFE_ENV.test(m[1])) {
      violations.push({ rel, rule: `e2e scope consumes env var "${m[1]}" — DB URLs in e2e scope must be E2E_/TEST_/LOCAL_-prefixed (never DATABASE_URL/PROD*)` });
    }
  }
}

if (violations.length === 0) {
  process.stdout.write(`${GREEN}✅ ${NAME}${RESET} — ${scanned} e2e-scope file(s) scanned; no remote DB targets.\n`);
  process.exit(0);
}
process.stderr.write(`${RED}❌ ${NAME}:${RESET} ${violations.length} violation(s)\n`);
for (const v of violations) process.stderr.write(`  [${v.rel}] ${v.rule}\n`);
process.stderr.write(`Per E2E_TESTING.yaml.db_safety — never real/remote DBs from e2e; local or e2e-db only.\n`);
process.exit(1);
